const charges = $input.item.json.data || [];
const successful = charges.filter(c => c.paid && !c.refunded);

const revenue = successful.reduce((sum, c) => sum + c.amount, 0) / 100;
const refunds = charges.reduce((sum, c) => sum + (c.amount_refunded || 0), 0) / 100;
const recurringRevenue = successful
  .filter(c => c.invoice)
  .reduce((sum, c) => sum + c.amount, 0) / 100;

return [{ json: { revenue, refunds, recurring_revenue: recurringRevenue } }];

const metaData = $('HTTP Request: Meta Ads - Weekly Insights').item.json.data || [];
const metaSpend = metaData.reduce((sum, r) => sum + parseFloat(r.spend || 0), 0);
const metaConversions = metaData.reduce((sum, r) => {
  const purchaseAction = (r.actions || []).find(a => a.action_type === 'purchase');
  return sum + (purchaseAction ? parseInt(purchaseAction.value, 10) : 0);
}, 0);

const googleResults = $('HTTP Request: Google Ads - Weekly Insights').item.json.results || [];
const googleSpend = googleResults.reduce((sum, r) => sum + ((r.metrics && r.metrics.costMicros) || 0), 0) / 1000000;
const googleConversions = googleResults.reduce((sum, r) => sum + ((r.metrics && r.metrics.conversions) || 0), 0);

const adSpend = metaSpend + googleSpend;
const conversions = metaConversions + googleConversions;
const cac = conversions > 0 ? adSpend / conversions : null;

return [{ json: { ad_spend: adSpend, conversions, cac } }];

const wonDeals = $('HTTP Request: HubSpot - Deals Won This Week').item.json.results || [];
const pipelineDeals = $('HTTP Request: HubSpot - Open Pipeline Value').item.json.results || [];

const dealsWonCount = wonDeals.length;
const dealsWonValue = wonDeals.reduce((sum, d) => sum + (parseFloat(d.properties.amount) || 0), 0);
const pipelineValue = pipelineDeals.reduce((sum, d) => sum + (parseFloat(d.properties.amount) || 0), 0);
const pipelineCount = pipelineDeals.length;

return [{ json: { deals_won_count: dealsWonCount, deals_won_value: dealsWonValue, pipeline_value: pipelineValue, pipeline_count: pipelineCount } }];

const stripe = $('Code: Aggregate Stripe Metrics').item.json;
const ads = $('Code: Aggregate Ad Spend & Conversions').item.json;
const crm = $('Code: Aggregate CRM Metrics').item.json;

return [{
  json: {
    week_ending: $now.toFormat('yyyy-MM-dd'),
    ...stripe,
    ...ads,
    ...crm
  }
}];

const current = $('Code: Combine This Week\'s Metrics').item.json;
const history = $input.all().map(i => i.json);

const metricKeys = ['revenue', 'refunds', 'recurring_revenue', 'ad_spend', 'conversions', 'cac', 'deals_won_value', 'pipeline_value'];

function trailingAvg(key) {
  const values = history.map(h => Number(h[key]) || 0).filter(v => !isNaN(v));
  if (!values.length) return null;
  return values.reduce((a, b) => a + b, 0) / values.length;
}

const trends = {};
for (const key of metricKeys) {
  const avg = trailingAvg(key);
  const curVal = Number(current[key]) || 0;
  const pctVsAvg = avg && avg !== 0 ? ((curVal - avg) / avg) * 100 : null;
  trends[key] = { current: curVal, trailing_avg: avg, pct_vs_avg: pctVsAvg };
}

const flags = [];
const adSpendTrend = trends['ad_spend'];
const conversionsTrend = trends['conversions'];
if (adSpendTrend.pct_vs_avg !== null && conversionsTrend.pct_vs_avg !== null) {
  if (adSpendTrend.pct_vs_avg > 0 && conversionsTrend.pct_vs_avg <= -15) {
    flags.push(`\u26a0\ufe0f Ad spend is up ${adSpendTrend.pct_vs_avg.toFixed(1)}% vs. the 4-week average while conversions dropped ${Math.abs(conversionsTrend.pct_vs_avg).toFixed(1)}% \u2014 investigate campaign ROI before spending more.`);
  }
}
if (trends['refunds'].pct_vs_avg !== null && trends['refunds'].pct_vs_avg > 25) {
  flags.push(`\u26a0\ufe0f Refunds are up ${trends['refunds'].pct_vs_avg.toFixed(1)}% vs. the 4-week average.`);
}

return [{ json: { ...current, trends, flags } }];

const t = $input.item.json;

function fmtMoney(v) { return '$' + (Number(v) || 0).toLocaleString(undefined, { minimumFractionDigits: 0, maximumFractionDigits: 0 }); }
function fmtDelta(pct) {
  if (pct === null || pct === undefined) return 'n/a';
  const arrow = pct > 0 ? '\u2b06\ufe0f' : (pct < 0 ? '\u2b07\ufe0f' : '\u27a1\ufe0f');
  return `${arrow} ${pct.toFixed(1)}% vs 4wk avg`;
}

const rows = [
  ['Revenue', fmtMoney(t.trends.revenue.current), fmtDelta(t.trends.revenue.pct_vs_avg)],
  ['Recurring Revenue', fmtMoney(t.trends.recurring_revenue.current), fmtDelta(t.trends.recurring_revenue.pct_vs_avg)],
  ['Refunds', fmtMoney(t.trends.refunds.current), fmtDelta(t.trends.refunds.pct_vs_avg)],
  ['Ad Spend', fmtMoney(t.trends.ad_spend.current), fmtDelta(t.trends.ad_spend.pct_vs_avg)],
  ['Conversions', t.trends.conversions.current, fmtDelta(t.trends.conversions.pct_vs_avg)],
  ['CAC', fmtMoney(t.trends.cac.current), fmtDelta(t.trends.cac.pct_vs_avg)],
  ['Deals Won', fmtMoney(t.trends.deals_won_value.current), fmtDelta(t.trends.deals_won_value.pct_vs_avg)],
  ['Pipeline Value', fmtMoney(t.trends.pipeline_value.current), fmtDelta(t.trends.pipeline_value.pct_vs_avg)]
];

const tableRows = rows.map(r => `| ${r[0]} | ${r[1]} | ${r[2]} |`).join('\n');
const flagsSection = t.flags && t.flags.length
  ? `\n\n### Flags\n\n${t.flags.map(f => `- ${f}`).join('\n')}`
  : '\n\n### Flags\n\nNo warning flags this week \u2705';

const markdown = `# Weekly Business Health Digest \u2014 Week Ending ${t.week_ending}\n\n`
  + `| Metric | This Week | Trend |\n|---|---|---|\n${tableRows}`
  + flagsSection;

return [{ json: { ...t, markdown_report: markdown } }];

